module rffe_register(
  input  logic clk,
  input  logic rst_n,
  input  logic sclk,
  input  logic sdata,
  output logic sdata_out,
  output logic sdata_oe
);

  logic sclk_d, sdata_d;
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      sclk_d  <= 1'b0;
      sdata_d <= 1'b0;
    end else begin
      sclk_d  <= sclk;
      sdata_d <= sdata;
    end
  end

  wire rise = sclk & ~sclk_d;
  wire fall = ~sclk & sclk_d;

  localparam [3:0] S_IDLE=0, S_USID=1, S_CMD=2, S_CPAR=3, S_WDATA=4,
                   S_WPAR=5, S_RPARK=6, S_RDATA=7, S_RPAR=8, S_RBP=9;

  logic [3:0] state, cnt;
  logic [7:0] cmd, wdat, rdat;
  logic [7:0] mem [0:15];
  integer i;
  logic dout, doe;

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      state <= S_IDLE;
      cnt   <= 4'd0;
      cmd   <= 8'd0;
      wdat  <= 8'd0;
      rdat  <= 8'd0;
      dout  <= 1'b0;
      doe   <= 1'b0;
      for (i = 0; i < 16; i = i + 1) mem[i] <= 8'hFF;
    end else begin
      case (state)
        S_IDLE: begin
          doe  <= 1'b0;
          dout <= 1'b0;
          if (rise && sdata_d) begin
            state <= S_USID;
            cnt   <= 4'd0;
          end
        end
        S_USID: if (rise) begin
          if (cnt == 4'd3) begin
            state <= S_CMD;
            cnt   <= 4'd0;
          end else cnt <= cnt + 4'd1;
        end
        S_CMD: if (rise) begin
          cmd <= {cmd[6:0], sdata_d};
          if (cnt == 4'd7) begin
            state <= S_CPAR;
            cnt   <= 4'd0;
          end else cnt <= cnt + 4'd1;
        end
        S_CPAR: if (rise) begin
          if (cmd[7:5] == 3'b010) begin
            state <= S_WDATA;
            cnt   <= 4'd0;
            wdat  <= 8'd0;
          end else if (cmd[7:5] == 3'b011) begin
            state <= S_RPARK;
            cnt   <= 4'd0;
          end else begin
            state <= S_IDLE;
          end
        end
        S_WDATA: if (rise) begin
          wdat <= {wdat[6:0], sdata_d};
          if (cnt == 4'd7) begin
            state <= S_WPAR;
            cnt   <= 4'd0;
          end else cnt <= cnt + 4'd1;
        end
        S_WPAR: if (rise) begin
          if (cmd[4:0] <= 5'd15) begin
            mem[cmd[3:0]] <= mem[cmd[3:0]] & ~wdat;
          end
          state <= S_IDLE;
        end
        S_RPARK: if (rise) begin
          if (cmd[4:0] <= 5'd15) begin
            rdat <= mem[cmd[3:0]];
            dout <= mem[cmd[3:0]][7];
            doe  <= 1'b1;
          end
          state <= S_RDATA;
          cnt   <= 4'd0;
        end
        S_RDATA: if (fall) begin
          if (cnt == 4'd7) begin
            dout  <= ~(^rdat);
            state <= S_RPAR;
          end else begin
            dout <= rdat[6 - cnt];
            cnt  <= cnt + 4'd1;
          end
        end
        S_RPAR: if (fall) begin
          dout  <= 1'b0;
          state <= S_RBP;
        end
        S_RBP: if (fall) begin
          doe   <= 1'b0;
          state <= S_IDLE;
        end
        default: state <= S_IDLE;
      endcase
    end
  end

  assign sdata_out = dout;
  assign sdata_oe  = doe;

endmodule
